  // Код страницы с настоящим выводом: data/code/*.py, запуск и вставка — data/inject.py
  const CODE = /*code:start*/{"four": {"title": "Четыре способа сравнить суммы покупок в одном эксперименте", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nab = pd.read_csv(\"data/inference/ab.csv\")     # учебный A/B-тест новой корзины, строка — пользователь\na = ab.query(\"group == 'A' and paid == 1\").amount.to_numpy(float)\nb = ab.query(\"group == 'B' and paid == 1\").amount.to_numpy(float)\nprint(f\"чеков:   А {len(a)}, Б {len(b)}\")\nprint(f\"среднее: А {a.mean():.0f}, Б {b.mean():.0f} ₽\")\nprint(f\"медиана: А {np.median(a):.0f}, Б {np.median(b):.0f} ₽\")\n\n\ndef diff_means(x, y, axis):                   # статистика перестановочного теста\n    return x.mean(axis=axis) - y.mean(axis=axis)\n\n\np = {\n    \"t Стьюдента\": stats.ttest_ind(b, a).pvalue,                  # общая дисперсия\n    \"t Уэлча\": stats.ttest_ind(b, a, equal_var=False).pvalue,\n    \"Манн — Уитни\": stats.mannwhitneyu(b, a).pvalue,\n    \"перестановки\": stats.permutation_test(\n        (b, a), diff_means, vectorized=True, n_resamples=9_999, rng=604).pvalue,\n}\nfor name, pv in p.items():\n    print(f\"{name:13s} p = {pv:.3f}\")\n\nu = stats.mannwhitneyu(b, a).statistic\nprint(f\"U/(nА·nБ) с половинным весом совпадений = {u / (len(a) * len(b)):.3f}\")\nprint(f\"чеков дороже 15 000 ₽: А {(a > 15_000).mean():.1%}, Б {(b > 15_000).mean():.1%}\")", "out": "чеков:   А 649, Б 767\nсреднее: А 4562, Б 4647 ₽\nмедиана: А 3200, Б 3400 ₽\nt Стьюдента   p = 0.767\nt Уэлча       p = 0.769\nМанн — Уитни  p = 0.130\nперестановки  p = 0.790\nU/(nА·nБ) с половинным весом совпадений = 0.523\nчеков дороже 15 000 ₽: А 3.4%, Б 2.7%"}, "alpha_sim": {"title": "На малых выборках чеков с длинным хвостом тест реже замечает рост на 20%", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nfrom scipy import stats\n\nrng = np.random.default_rng(604)\nR = 10_000                                    # повторов на строку таблицы\nprint(\"σ      n   ложных:  Уэлч   М — У    мощность при +20%:   Уэлч   М — У\")\nfor sigma in (0.6, 1.5):                      # 0,6 — как розничные чеки, 1,5 — очень тяжёлый хвост\n    for n in (10, 30, 100, 1000):\n        a = rng.lognormal(0, sigma, (R, n))\n        b = rng.lognormal(0, sigma, (R, n))   # та же форма: нулевая гипотеза верна\n        row = []\n        for k in (1.0, 1.2):                  # без эффекта и с ростом на 20%\n            row.append((stats.ttest_ind(a, b * k, axis=1, equal_var=False).pvalue < 0.05).mean())\n            row.append((stats.mannwhitneyu(a, b * k, axis=1).pvalue < 0.05).mean())\n        print(f\"{sigma:.1f} {n:6d}   {row[0]:13.1%} {row[1]:7.1%} {row[2]:26.1%} {row[3]:7.1%}\")", "out": "σ      n   ложных:  Уэлч   М — У    мощность при +20%:   Уэлч   М — У\n0.6     10            3.6%    4.2%                       7.5%    8.4%\n0.6     30            4.6%    4.7%                      18.3%   19.4%\n0.6    100            4.8%    4.8%                      50.8%   55.7%\n0.6   1000            5.1%    5.1%                     100.0%  100.0%\n1.5     10            1.7%    4.3%                       2.0%    4.8%\n1.5     30            3.1%    4.9%                       4.1%    7.1%\n1.5    100            3.6%    5.3%                       7.4%   13.6%\n1.5   1000            4.6%    5.0%                      34.2%   74.5%"}, "chi": {"title": "Связь источника визита с покупкой и сравнение двух долей оплативших", "badge": "проверено: Python 3.13, SciPy 1.18.1, statsmodels 0.15.0", "lang": "python", "code": "import pandas as pd\nfrom scipy import stats\nfrom statsmodels.stats.proportion import proportions_ztest\n\n# 1. Источник визита × покупка: 100 000 учебных визитов\nv = pd.read_csv(\"data/probability/visits.csv\")\ntable = pd.crosstab(v.source, v.bought)\nres = stats.chi2_contingency(table)\nprint(table)\nprint(f\"хи-квадрат = {res.statistic:.1f}, степеней свободы {res.dof}, p = {res.pvalue:.1e}\")\nprint(\"ожидаемые покупки без связи:\", res.expected_freq[:, 1].round(1))\nprint(\"доля покупок:\", (table[1] / table.sum(axis=1)).round(3).to_dict())\n\n# 2. Доля оплативших в A/B-тесте: двусторонний z-тест с общей оценкой доли и хи-квадрат без поправки дают одинаковое p\nab = pd.read_csv(\"data/inference/ab.csv\")\npaid = ab.groupby(\"group\").paid.agg([\"sum\", \"count\"])\nz, p = proportions_ztest(paid[\"sum\"], paid[\"count\"])\nchi2 = stats.chi2_contingency(pd.crosstab(ab.group, ab.paid), correction=False)\nprint(paid.assign(share=paid[\"sum\"] / paid[\"count\"]).round(4))\nprint(f\"z = {z:.3f}, z² = {z ** 2:.2f}, p = {p:.4f}\")\nprint(f\"хи-квадрат = {chi2.statistic:.2f}, p = {chi2.pvalue:.4f}\")", "out": "bought        0     1\nsource               \nорганика  53802  1307\nрассылка  14146   897\nреклама   28676  1172\nхи-квадрат = 506.8, степеней свободы 2, p = 9.1e-111\nожидаемые покупки без связи: [1860.5  507.9 1007.7]\nдоля покупок: {'органика': 0.024, 'рассылка': 0.06, 'реклама': 0.039}\n       sum  count   share\ngroup                    \nA      649  20000  0.0324\nB      767  20000  0.0384\nz = -3.193, z² = 10.19, p = 0.0014\nхи-квадрат = 10.19, p = 0.0014"}, "mw_median": {"title": "Критерий Манна — Уитни обнаруживает различие распределений при равных медианах", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nchecks = pd.read_csv(\"data/probability/checks.csv\").amount.to_numpy(float)\nmed = np.median(checks)                       # 3 080 ₽\n\n\ndef upsell(x):\n    # вариант Б: заказам дороже медианы предложили допродажу, они выросли на 30%\n    return np.where(x > med, x * 1.3, x)\n\n\nprint(\"медианы совокупностей:\", med, np.median(upsell(checks)))\n\nrng = np.random.default_rng(604)\na = rng.choice(checks, 1000)\nb = upsell(rng.choice(checks, 1000))\nres = stats.mannwhitneyu(b, a)\nprint(f\"медианы выборок: А {np.median(a):.0f}, Б {np.median(b):.0f} ₽\")\nprint(f\"Манн — Уитни: p = {res.pvalue:.1e}, U/(nА·nБ) с половинным весом совпадений = {res.statistic / (len(a) * len(b)):.3f}\")\n\n# 10 000 пар групп по 200 чеков: как часто тест значим\npv = stats.mannwhitneyu(upsell(rng.choice(checks, (10_000, 200))), rng.choice(checks, (10_000, 200)), axis=1).pvalue\nprint(f\"значим в {(pv < 0.05).mean():.1%} повторов при равных медианах совокупностей\")", "out": "медианы совокупностей: 3080.0 3080.0\nмедианы выборок: А 3175, Б 3075 ₽\nМанн — Уитни: p = 3.8e-04, U/(nА·nБ) с половинным весом совпадений = 0.546\nзначим в 37.9% повторов при равных медианах совокупностей"}, "pretest": {"title": "Отклонение чеков от нормальности ещё не исключает тест Уэлча", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nchecks = pd.read_csv(\"data/probability/checks.csv\").amount.to_numpy(float)\nrng = np.random.default_rng(604)\nR = 2_000                                     # пар групп на каждый размер\nprint(\"    n   Шапиро — Уилк отверг нормальность   ложных у Уэлча\")\nfor n in (10, 30, 300, 3000):\n    a = rng.choice(checks, (R, n))\n    b = rng.choice(checks, (R, n))            # эффекта нет\n    sw = (stats.shapiro(a, axis=1).pvalue < 0.05).mean()\n    welch = (stats.ttest_ind(a, b, axis=1, equal_var=False).pvalue < 0.05).mean()\n    print(f\"{n:5d}   {sw:20.1%}   {welch:28.1%}\")", "out": "    n   Шапиро — Уилк отверг нормальность   ложных у Уэлча\n   10                  49.0%                           2.6%\n   30                  94.0%                           2.9%\n  300                 100.0%                           5.0%\n 3000                 100.0%                           5.1%"}, "welch_student": {"title": "При большем разбросе в малой группе тест Стьюдента даёт 25,5% ложных срабатываний", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nfrom scipy import stats\n\nrng = np.random.default_rng(604)\nR = 10_000\ncases = {                                     # (n, σ) группы А и (n, σ) группы Б; средние равны\n    \"разбросы равны\": ((30, 20), (120, 20)),\n    \"малая группа шумнее\": ((30, 30), (120, 10)),\n    \"большая группа шумнее\": ((30, 10), (120, 30)),\n}\nprint(f\"{'':22s}  ложных: Стьюдент   Уэлч\")\nfor name, ((na, sa), (nb, sb)) in cases.items():\n    a = rng.normal(100, sa, (R, na))\n    b = rng.normal(100, sb, (R, nb))\n    st = (stats.ttest_ind(a, b, axis=1).pvalue < 0.05).mean()\n    we = (stats.ttest_ind(a, b, axis=1, equal_var=False).pvalue < 0.05).mean()\n    print(f\"{name:22s}  {st:15.1%} {we:6.1%}\")", "out": "                        ложных: Стьюдент   Уэлч\nразбросы равны                     4.9%   5.0%\nмалая группа шумнее               25.5%   4.7%\nбольшая группа шумнее              0.1%   5.3%"}, "clusters": {"title": "Если анализировать сессии как независимые наблюдения, ложные срабатывания учащаются", "badge": "проверено: Python 3.13, SciPy 1.18.1", "lang": "python", "code": "import numpy as np\nfrom scipy import stats\n\nrng = np.random.default_rng(604)\nR, users, per = 10_000, 60, 5                 # в группе 60 пользователей по 5 сессий\n\n\ndef group():\n    level = rng.lognormal(np.log(3000), 0.6, (R, users))         # у каждого свой уровень чека\n    return np.repeat(level, per, axis=1) * rng.lognormal(-0.125, 0.5, (R, users * per))\n\n\na, b = group(), group()                       # эффекта нет\nwelch = (stats.ttest_ind(a, b, axis=1, equal_var=False).pvalue < 0.05).mean()\nmw = (stats.mannwhitneyu(a, b, axis=1).pvalue < 0.05).mean()\nua = a.reshape(R, users, per).mean(axis=2)    # одна строка на пользователя\nub = b.reshape(R, users, per).mean(axis=2)\nuser = (stats.ttest_ind(ua, ub, axis=1, equal_var=False).pvalue < 0.05).mean()\nprint(f\"300 сессий как независимые, Уэлч:        {welch:.1%}\")\nprint(f\"300 сессий как независимые, Манн — Уитни: {mw:.1%}\")\nprint(f\"60 средних по пользователям, Уэлч:       {user:.1%}\")", "out": "300 сессий как независимые, Уэлч:        26.9%\n300 сессий как независимые, Манн — Уитни: 28.3%\n60 средних по пользователям, Уэлч:       4.9%"}}/*code:end*/;

  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const seg = (p, a, b) => clamp((p - a) / (b - a), 0, 1);
  const ease = t => (t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
  // число по-русски: пробел между разрядами, десятичная запятая
  const num = (v, d = 0) => { const s = Math.abs(v).toFixed(d).split('.'); return (v < 0 ? '−' : '') + s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (s[1] ? ',' + s[1] : ''); };
  const pct = (v, d = 1) => `${num(v * 100, d)}%`;
