      bad: () => ({ cap: 'выросли только чеки дороже медианы', mh: svgBox(bars(SD.mw_bad.ha, SC.bar) + stepLine(SD.mw_bad.hb, SC.bad, Math.max(...SD.mw_bad.ha, ...SD.mw_bad.hb)), vline(3080 / 16000 * 100, SC.yel)), ax: ['0', '≥ 16 тыс. ₽'], stat: `при равных медианах p < 0,05 в ${pct(SD.mw_bad.rej, 0)}`, call: `медиана ${num(SD.mw_bad.med_a)} = ${num(SD.mw_bad.med_b)}` })
