      welch: { t: 't-тест Уэлча', en: 'Welch\'s t-test', d: 'Критерий для сравнения средних двух независимых групп. Дисперсию в каждой группе оценивают отдельно.' },
      student: { t: 't-тест Стьюдента', en: 'Student\'s t-test', d: 'В этом уроке — критерий для двух независимых групп, в котором предполагают равенство дисперсий и оценивают общую дисперсию.' },
